/* --- components/fab/fab.js --- */
/* ARG UI fab: button.arg-fab[data-arg-fab][data-arg-target="selector"][data-arg-class="tên-class"].
   Bấm thì bật tắt class trên các phần tử khớp selector trong vùng [data-arg-listbar-scope] gần nhất (hoặc cả trang), cập nhật aria-pressed. */
(function () {
  'use strict';
  ARG.register('fab', function (root) {
    ARG.$$('[data-arg-fab]', root).forEach(function (b) {
      if (!ARG.once(b, 'fab')) return;
      b.addEventListener('click', function () {
        var scope = b.closest('[data-arg-listbar-scope]') || document, on = b.getAttribute('aria-pressed') !== 'true';
        ARG.$$(b.getAttribute('data-arg-target'), scope).forEach(function (el) { el.classList.toggle(b.getAttribute('data-arg-class'), on); });
        b.setAttribute('aria-pressed', String(on));
      });
    });
  });
})();

/* --- components/keyboard/keyboard.js --- */
/* ARG UI keyboard: bàn phím mô phỏng điện thoại, hiện khi bấm vào ô nhập trong .arg-page.
   - Kiểu bàn phím theo ô nhập: inputmode="numeric" hoặc type="number" → phím số; inputmode="decimal" → phím số có dấu phẩy; type="tel" hoặc inputmode="tel" → phím số điện thoại;
     còn lại → bàn phím chữ (có trang số và ký hiệu). Ô type="date", checkbox... không hiện bàn phím.
   - enterkeyhint (search, go, next) đổi nhãn phím xuống dòng; mặc định "Xong". Nút Xong trên thanh công cụ đóng bàn phím.
   - Phím gõ vào ô bằng setRangeText và bắn "input", nên các JS lắng nghe ô nhập vẫn chạy. Phím xoá giữ để lặp.
   - Đặt inputmode="none" lên ô để bàn phím hệ điều hành không hiện cùng lúc. Bàn phím gõ thật vẫn dùng được.
   - [data-arg-kb-static="num|decimal|tel|alpha"] vẽ bản tĩnh để minh hoạ. Bắn "arg:keyboard" ({ open, mode }) trên document. */
(function () {
  'use strict';
  var SUB = { 2: 'ABC', 3: 'DEF', 4: 'GHI', 5: 'JKL', 6: 'MNO', 7: 'PQRS', 8: 'TUV', 9: 'WXYZ' };
  var ROWS = { abc: ['qwertyuiop', 'asdfghjkl', 'zxcvbnm'], sym: ['1234567890', '-/:;()₫&@"', '.,?!\''] };
  var NOKB = /^(checkbox|radio|date|time|datetime-local|month|week|range|color|file|button|submit|reset|image|hidden)$/;
  var kb, body, cur = null, st = { mode: 'alpha', page: 'abc', shift: 0 }, tShift = 0, hideT = 0, rep = 0, repI = 0;

  function btn(cls, label, attrs) { return '<button class="arg-kb__key ' + cls + '" type="button" tabindex="-1" ' + (attrs || '') + '>' + label + '</button>'; }
  function numpad(mode) {
    var h = '';
    for (var d = 1; d <= 9; d++) h += btn('', '<span>' + d + '</span>' + (SUB[d] ? '<span class="arg-kb__sub">' + SUB[d] + '</span>' : ''), 'data-ch="' + d + '" aria-label="' + d + '"');
    h += mode === 'tel' ? btn('arg-kb__key--bare', '<span class="arg-kb__glyph">+*#</span>', 'data-ch="+" aria-label="Dấu cộng"')
      : mode === 'decimal' ? btn('arg-kb__key--c', ',', 'data-ch="," aria-label="Dấu phẩy"') : '<span></span>';
    h += btn('arg-kb__key--c', '0', 'data-ch="0" aria-label="0"') + btn('arg-kb__key--bare', ARG.icon('backspace'), 'data-act="back" aria-label="Xoá"');
    return '<div class="arg-kb__num">' + h + '</div>';
  }
  function alpha() {
    var up = st.shift > 0, sym = st.page === 'sym', rows = ROWS[sym ? 'sym' : 'abc'], c = function (k) { return up && !sym ? k.toUpperCase() : k; };
    var key = function (k, extra) { return btn(extra || '', c(k), 'data-ch="' + c(k) + '"' + (sym ? '' : ' data-k="' + c(k) + '"') + ' aria-label="' + c(k) + '"'); };
    var h = rows[0].split('').map(function (k) { return key(k); }).join('');
    h += rows[1].split('').map(function (k, i) { return key(k, i === 0 && !sym ? 'arg-kb__key--off' : ''); }).join('');
    if (sym) h += '<span class="arg-kb__key--w7"></span>' + rows[2].split('').map(function (k) { return key(k); }).join('');
    else h += btn('arg-kb__key--fn arg-kb__key--w3' + (st.shift ? ' is-on' : ''), ARG.icon('arrow-fat-up'), 'data-act="shift" aria-label="Chữ hoa"') + rows[2].split('').map(function (k) { return key(k); }).join('');
    h += btn('arg-kb__key--fn arg-kb__key--w3', ARG.icon('backspace'), 'data-act="back" aria-label="Xoá"');
    h += btn('arg-kb__key--fn arg-kb__key--w5', sym ? 'ABC' : '123', 'data-act="page" aria-label="Đổi trang"') + btn('arg-kb__key--w10', 'dấu cách', 'data-ch=" " aria-label="Dấu cách"') + btn('arg-kb__key--fn arg-kb__key--w5', retLabel(), 'data-act="ret" aria-label="' + retLabel() + '"');
    return '<div class="arg-kb__alpha">' + h + '</div>';
  }
  function retLabel() { var h = cur && cur.getAttribute('enterkeyhint'); return { search: 'Tìm', go: 'Đi', next: 'Tiếp', send: 'Gửi', done: 'Xong' }[h] || 'Xong'; }
  function pad(mode) { return mode === 'alpha' ? alpha() : numpad(mode); }
  function frame(inner, bar) {
    return (bar ? '<div class="arg-kb__bar"><button class="arg-kb__done" type="button" tabindex="-1" data-act="done">' + ARG.icon('keyboard') + '<span>Xong</span></button></div>' : '') +
      '<div class="arg-kb__body">' + inner + '</div><div class="arg-kb__home"></div>';
  }
  function render() { body.innerHTML = pad(st.mode); }

  function modeOf(el) {
    var im = el.dataset.kbIm || el.getAttribute('inputmode') || '';
    if (el.type === 'tel' || im === 'tel') return 'tel';
    if (im === 'decimal') return 'decimal';
    if (im === 'numeric' || el.type === 'number') return 'numeric';
    return 'alpha';
  }
  function eligible(el) { return el && el.matches && el.matches('input, textarea') && !el.readOnly && !el.disabled && !NOKB.test(el.type || 'text') && !!el.closest('.arg-page'); }
  function mute(el) { if (eligible(el) && el.dataset.kbIm === undefined) { el.dataset.kbIm = el.getAttribute('inputmode') || ''; el.setAttribute('inputmode', 'none'); } }

  function sel(el) { try { return [el.selectionStart, el.selectionEnd]; } catch (e) { return [null, null]; } }
  function put(ch) {
    var el = cur; if (!el || (el.maxLength > 0 && el.value.length >= el.maxLength)) return;
    var s = sel(el);
    if (s[0] === null) el.value += ch; else el.setRangeText(ch, s[0], s[1], 'end');
    el.dispatchEvent(new Event('input', { bubbles: true }));
    if (st.shift === 1 && st.mode === 'alpha') { st.shift = 0; render(); }
  }
  function back() {
    var el = cur; if (!el) return;
    var s = sel(el);
    if (s[0] === null) el.value = el.value.slice(0, -1);
    else if (s[0] !== s[1]) el.setRangeText('', s[0], s[1], 'end');
    else if (s[0] > 0) el.setRangeText('', s[0] - 1, s[0], 'end');
    el.dispatchEvent(new Event('input', { bubbles: true }));
  }
  function act(a) {
    if (a === 'back') back();
    else if (a === 'done') { if (cur) cur.blur(); }
    else if (a === 'ret') { if (cur) { cur.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true })); cur.blur(); } }
    else if (a === 'page') { st.page = st.page === 'abc' ? 'sym' : 'abc'; render(); }
    else if (a === 'shift') { var n = Date.now(); st.shift = st.shift === 1 && n - tShift < 400 ? 2 : st.shift ? 0 : 1; tShift = n; render(); }
  }

  function open(el) {
    clearTimeout(hideT); cur = el; st.mode = modeOf(el); st.page = 'abc'; st.shift = 0; render();
    kb.hidden = false; document.documentElement.classList.add('arg-kb-open');
    requestAnimationFrame(function () { requestAnimationFrame(function () { kb.classList.add('is-open'); }); });
    setTimeout(function () {
      if (cur !== el) return;
      var r = el.getBoundingClientRect(), vis = window.innerHeight - kb.offsetHeight - 16;
      if (r.bottom > vis) window.scrollBy({ top: r.bottom - vis, behavior: 'smooth' });
    }, 280);
    document.dispatchEvent(new CustomEvent('arg:keyboard', { detail: { open: true, mode: st.mode } }));
  }
  function close() {
    cur = null; kb.classList.remove('is-open'); document.documentElement.classList.remove('arg-kb-open');
    hideT = setTimeout(function () { if (!cur) kb.hidden = true; }, 260);
    document.dispatchEvent(new CustomEvent('arg:keyboard', { detail: { open: false } }));
  }
  function stopRep() { clearTimeout(rep); clearInterval(repI); }

  ARG.register('keyboard', function (root) {
    ARG.$$('[data-arg-kb-static]', root).forEach(function (el) {
      if (!ARG.once(el, 'kbs')) return;
      var m = el.getAttribute('data-arg-kb-static'); st = { mode: m, page: 'abc', shift: 0 }; cur = null;
      el.classList.add('arg-kb', 'arg-kb--static'); el.setAttribute('aria-hidden', 'true'); el.innerHTML = frame(pad(m), true);
      ARG.init(el);
    });
    if (kb || !document.querySelector('.arg-page')) return;
    kb = document.createElement('div'); kb.className = 'arg-kb'; kb.hidden = true; kb.setAttribute('aria-hidden', 'true');
    kb.innerHTML = frame('', true); body = ARG.$('.arg-kb__body', kb); document.body.appendChild(kb); ARG.init(kb);
    ARG.$$('input, textarea', document).forEach(mute);
    document.addEventListener('pointerdown', function (e) { mute(e.target); }, true);
    document.addEventListener('focusin', function (e) { if (eligible(e.target)) { mute(e.target); open(e.target); } });
    document.addEventListener('focusout', function () {
      setTimeout(function () { if (!eligible(document.activeElement)) close(); else if (document.activeElement !== cur) open(document.activeElement); }, 0);
    });
    kb.addEventListener('mousedown', function (e) { e.preventDefault(); });
    kb.addEventListener('pointerdown', function (e) {
      var k = e.target.closest('.arg-kb__key, .arg-kb__done'); if (!k) return;
      e.preventDefault();
      var a = k.getAttribute('data-act'), ch = k.getAttribute('data-ch');
      if (ch !== null) put(ch); else if (a) act(a);
      if (a === 'back') { stopRep(); rep = setTimeout(function () { repI = setInterval(back, 70); }, 420); }
    });
    ['pointerup', 'pointercancel', 'pointerleave'].forEach(function (t) { kb.addEventListener(t, stopRep); });
  });
})();

/* --- components/datepicker/datepicker.js --- */
/* ARG UI datepicker: input[data-arg-datepicker] (readonly) trong .arg-control. Bấm ô, icon, hoặc phím Enter, Space thì bảng lịch trượt từ dưới lên.
   - Ô hiện ngày dd/mm/yyyy (không phụ thuộc ngôn ngữ máy); giá trị chuẩn yyyy-mm-dd nằm ở input.dataset.iso.
   - data-min, data-max (yyyy-mm-dd) trên ô: ngày ngoài khoảng bị tắt. Có thể đổi lúc chạy, bảng đọc lại mỗi lần mở.
   - "Hôm nay" lấy từ [data-arg-today="yyyy-mm-dd"] (đặt trên .arg-page để khớp dữ liệu mẫu), không có thì dùng ngày của máy.
   - Chọn ngày rồi bấm Chọn: ghi vào ô, bắn "change" (bubbles) trên ô và "arg:date" ({ iso }). Bấm Huỷ, Esc hoặc nền thì không đổi.
   - Bàn phím: mũi tên đổi ngày (trái phải ±1, lên xuống ±7), PageUp, PageDown đổi tháng, Enter, Space chọn. Bấm tiêu đề để chọn tháng và năm. */
(function () {
  'use strict';
  var MN = ['Tháng 1', 'Tháng 2', 'Tháng 3', 'Tháng 4', 'Tháng 5', 'Tháng 6', 'Tháng 7', 'Tháng 8', 'Tháng 9', 'Tháng 10', 'Tháng 11', 'Tháng 12'];
  var WD = ['T2', 'T3', 'T4', 'T5', 'T6', 'T7', 'CN'];
  var wrap, st = { v: 'day', y: 0, m: 0, sel: '', focus: '', input: null, min: '', max: '' };

  function pad(n) { return (n < 10 ? '0' : '') + n; }
  function iso(y, m, d) { var t = new Date(y, m, d); return t.getFullYear() + '-' + pad(t.getMonth() + 1) + '-' + pad(t.getDate()); }
  function parse(s) { var p = (s || '').split('-'); return p.length === 3 ? { y: +p[0], m: p[1] - 1, d: +p[2] } : null; }
  function fmt(s) { var p = parse(s); return pad(p.d) + '/' + pad(p.m + 1) + '/' + p.y; }
  function today() {
    var t = document.querySelector('[data-arg-today]'), s = t && t.getAttribute('data-arg-today');
    if (s) return s;
    var n = new Date(); return iso(n.getFullYear(), n.getMonth(), n.getDate());
  }
  function ok(s) { return (!st.min || s >= st.min) && (!st.max || s <= st.max); }
  function clamp(s) { return st.min && s < st.min ? st.min : st.max && s > st.max ? st.max : s; }
  function $(sel) { return ARG.$(sel, wrap); }

  function render() {
    var t = today(), h = '', title = $('.arg-datepicker__title span');
    if (st.v === 'day') {
      title.textContent = MN[st.m] + ', ' + st.y;
      var lead = (new Date(st.y, st.m, 1).getDay() + 6) % 7, n = new Date(st.y, st.m + 1, 0).getDate();
      for (var i = 0; i < lead; i++) h += '<span></span>';
      for (var d = 1; d <= n; d++) {
        var s = iso(st.y, st.m, d);
        h += '<button class="arg-datepicker__day" type="button" data-dp-day="' + s + '" tabindex="' + (s === st.focus ? 0 : -1) + '" aria-label="' + d + ' ' + MN[st.m].toLowerCase() + ', ' + st.y + '"' +
          (s === st.sel ? ' aria-pressed="true"' : ' aria-pressed="false"') + (s === t ? ' aria-current="date"' : '') + (ok(s) ? '' : ' disabled') + '>' + d + '</button>';
      }
      $('.arg-datepicker__wd').hidden = false;
      $('.arg-datepicker__grid').className = 'arg-datepicker__grid';
    } else {
      title.textContent = String(st.y);
      var tp = parse(t), sp = parse(st.sel);
      for (var k = 0; k < 12; k++) {
        var on = sp && sp.y === st.y && sp.m === k, enabled = ok(iso(st.y, k, 1)) || ok(iso(st.y, k, new Date(st.y, k + 1, 0).getDate()));
        h += '<button class="arg-datepicker__month" type="button" data-dp-month="' + k + '" aria-pressed="' + !!on + '"' + (tp.y === st.y && tp.m === k ? ' aria-current="date"' : '') + (enabled ? '' : ' disabled') + '>Th' + (k + 1) + '</button>';
      }
      $('.arg-datepicker__wd').hidden = true;
      $('.arg-datepicker__grid').className = 'arg-datepicker__grid arg-datepicker__grid--month';
    }
    $('.arg-datepicker__grid').innerHTML = h;
    $('[data-dp-ok]').disabled = !st.sel || !ok(st.sel);
    $('[data-dp-today]').disabled = !ok(t);
    $('[data-dp-prev]').disabled = st.v === 'day' ? !!st.min && iso(st.y, st.m, 1) <= st.min : !!st.min && st.y <= +st.min.slice(0, 4);
    $('[data-dp-next]').disabled = st.v === 'day' ? !!st.max && iso(st.y, st.m + 1, 1) > st.max : !!st.max && st.y >= +st.max.slice(0, 4);
  }
  function focusDay() { var b = $('[data-dp-day][tabindex="0"]') || $('[data-dp-month]:not(:disabled)'); if (b) b.focus(); }
  function go(delta) {   // đổi tháng (ngày) hoặc năm (tháng), giữ ngày đang chọn tiêu điểm nếu còn
    if (st.v === 'day') {
      var f = parse(st.focus), n = new Date(st.y, st.m + delta, 1);
      st.y = n.getFullYear(); st.m = n.getMonth();
      st.focus = clamp(iso(st.y, st.m, Math.min(f.d, new Date(st.y, st.m + 1, 0).getDate())));
      var q = parse(st.focus); st.y = q.y; st.m = q.m;
    } else st.y += delta;
    render();
  }
  function build() {
    wrap = document.createElement('div'); wrap.className = 'arg-offcanvas-wrap'; wrap.id = 'arg-dp'; wrap.hidden = true; wrap.setAttribute('data-arg-offcanvas', '');
    wrap.innerHTML = '<aside class="arg-offcanvas arg-offcanvas--bottom arg-datepicker" role="dialog" aria-modal="true" aria-labelledby="arg-dp-t">' +
      '<div class="arg-modal__header"><h4 class="arg-modal__title" id="arg-dp-t">Chọn ngày</h4><button class="arg-icon-btn" type="button" data-arg-close aria-label="Đóng">' + ARG.icon('x', 'i--20') + '</button></div>' +
      '<div class="arg-datepicker__body"><div class="arg-datepicker__nav"><button type="button" data-dp-prev aria-label="Tháng trước">' + ARG.icon('caret-left') + '</button>' +
      '<button class="arg-datepicker__title" type="button" aria-live="polite"><span></span>' + ARG.icon('caret-down') + '</button><button type="button" data-dp-next aria-label="Tháng sau">' + ARG.icon('caret-right') + '</button></div>' +
      '<div class="arg-datepicker__wd" aria-hidden="true">' + WD.map(function (w) { return '<span>' + w + '</span>'; }).join('') + '</div><div class="arg-datepicker__grid" role="group"></div></div>' +
      '<div class="arg-modal__footer arg-datepicker__foot"><button class="arg-btn arg-btn--text arg-datepicker__today" type="button" data-dp-today>Hôm nay</button>' +
      '<button class="arg-btn arg-btn--tertiary" type="button" data-arg-close>Huỷ</button><button class="arg-btn arg-btn--primary" type="button" data-dp-ok>Chọn</button></div></aside>';
    (document.querySelector('.arg-page') || document.body).appendChild(wrap);
    wrap.addEventListener('click', function (e) {
      var b = e.target.closest('button'); if (!b || b.disabled) return;
      if (b.hasAttribute('data-dp-prev')) go(-1);
      else if (b.hasAttribute('data-dp-next')) go(1);
      else if (b.classList.contains('arg-datepicker__title')) { st.v = st.v === 'day' ? 'month' : 'day'; render(); focusDay(); }
      else if (b.hasAttribute('data-dp-day')) { st.sel = st.focus = b.getAttribute('data-dp-day'); render(); focusDay(); }
      else if (b.hasAttribute('data-dp-month')) {
        st.m = +b.getAttribute('data-dp-month'); st.v = 'day';
        var f = parse(st.focus); st.focus = clamp(iso(st.y, st.m, Math.min(f.d, new Date(st.y, st.m + 1, 0).getDate()))); var q = parse(st.focus); st.y = q.y; st.m = q.m; render(); focusDay();
      } else if (b.hasAttribute('data-dp-today')) { var t = today(), p = parse(t); st.sel = st.focus = t; st.y = p.y; st.m = p.m; st.v = 'day'; render(); focusDay(); }
      else if (b.hasAttribute('data-dp-ok')) {
        var inp = st.input; inp.value = fmt(st.sel); inp.dataset.iso = st.sel;
        inp.dispatchEvent(new Event('change', { bubbles: true }));
        inp.dispatchEvent(new CustomEvent('arg:date', { bubbles: true, detail: { iso: st.sel } }));
        ARG.closeLayer(wrap);
      }
    });
    wrap.addEventListener('keydown', function (e) {
      var d = e.target.closest && e.target.closest('[data-dp-day]'); if (!d) return;
      var f = parse(st.focus), step = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: -7, ArrowDown: 7 }[e.key], nx;
      if (step) nx = iso(f.y, f.m, f.d + step);
      else if (e.key === 'PageUp' || e.key === 'PageDown') nx = iso(f.y, f.m + (e.key === 'PageUp' ? -1 : 1), f.d);
      else return;
      e.preventDefault();
      if (!ok(nx)) return;
      var p = parse(nx); st.focus = nx; st.y = p.y; st.m = p.m; render(); focusDay();
    });
  }
  function open(input) {
    if (!wrap) build();
    st.input = input; st.v = 'day'; st.min = input.dataset.min || ''; st.max = input.dataset.max || ''; st.sel = input.dataset.iso || '';
    st.focus = clamp(st.sel || today()); var p = parse(st.focus); st.y = p.y; st.m = p.m;
    render(); ARG.openLayer(wrap, input);
    setTimeout(focusDay, 60);
  }

  ARG.register('datepicker', function (root) {
    ARG.$$('input[data-arg-datepicker]', root).forEach(function (inp) {
      if (!ARG.once(inp, 'datepicker')) return;
      inp.readOnly = true; inp.setAttribute('aria-haspopup', 'dialog');
      var box = inp.closest('.arg-control') || inp;
      box.addEventListener('click', function () { if (!inp.disabled) open(inp); });
      inp.addEventListener('keydown', function (e) { if ((e.key === 'Enter' || e.key === ' ') && !inp.disabled) { e.preventDefault(); open(inp); } });
    });
  });
})();
